import re


_COMPONENT = re.compile(r"[0-9]+(?:\.[0-9]+)?(?:ms|[wdhms])")
_COMPONENTS = re.compile(
    r"[0-9]+(?:\.[0-9]+)?(?:ms|[wdhms])"
    r"(?: ?[0-9]+(?:\.[0-9]+)?(?:ms|[wdhms]))*"
)

_UNIT_MILLISECONDS = {
    "w": 7 * 24 * 60 * 60 * 1000,
    "d": 24 * 60 * 60 * 1000,
    "h": 60 * 60 * 1000,
    "m": 60 * 1000,
    "s": 1000,
    "ms": 1,
}
_UNIT_ORDER = {unit: index for index, unit in enumerate(("w", "d", "h", "m", "s", "ms"))}


def parse_duration(text):
    """Return the duration described by `text` in whole milliseconds. See TASK.md."""
    if not isinstance(text, str):
        raise TypeError("duration must be a string")

    value = text.strip()
    negative = value.startswith("-")
    if negative:
        value = value[1:]
    if not value or value.startswith("+") or not _COMPONENTS.fullmatch(value):
        raise ValueError("invalid duration")

    total_numerator = 0
    total_denominator = 1
    previous_order = -1
    components = list(_COMPONENT.finditer(value))
    for index, match in enumerate(components):
        if index and value[components[index - 1].end():match.start()] not in ("", " "):
            raise ValueError("invalid duration")

        number = match.group()[: match.group().rfind(next(
            unit for unit in ("ms", "w", "d", "h", "m", "s")
            if match.group().endswith(unit)
        ))]
        unit = match.group()[len(number):]
        order = _UNIT_ORDER[unit]
        if order <= previous_order:
            raise ValueError("invalid duration")
        previous_order = order

        if "." in number:
            if index != len(components) - 1:
                raise ValueError("invalid duration")
            whole, fraction = number.split(".")
            numerator = int(whole + fraction)
            denominator = 10 ** len(fraction)
        else:
            numerator = int(number)
            denominator = 1
        total_numerator = total_numerator * denominator + numerator * _UNIT_MILLISECONDS[unit] * total_denominator
        total_denominator *= denominator

    quotient, remainder = divmod(total_numerator, total_denominator)
    if remainder * 2 >= total_denominator:
        quotient += 1
    return -quotient if negative else quotient
